CREATE TABLE IF NOT EXISTS auth_policy(id INTEGER PRIMARY KEY CHECK(id=1),google_enabled INTEGER NOT NULL,signup_enabled INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS auth_admins(user_id TEXT PRIMARY KEY REFERENCES users(id));
CREATE TABLE IF NOT EXISTS auth_passwords(user_id TEXT PRIMARY KEY REFERENCES users(id),email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_security(user_id TEXT PRIMARY KEY REFERENCES users(id),handle TEXT NOT NULL UNIQUE,totp_secret TEXT,last_totp_step INTEGER NOT NULL DEFAULT -1,epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS auth_recovery_codes(user_id TEXT NOT NULL REFERENCES users(id),hash TEXT NOT NULL UNIQUE,PRIMARY KEY(user_id,hash));
CREATE TABLE IF NOT EXISTS auth_passkeys(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),label TEXT NOT NULL,credential TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS auth_passkeys_user ON auth_passkeys(user_id);
CREATE TABLE IF NOT EXISTS auth_account_tokens(hash TEXT PRIMARY KEY,purpose TEXT NOT NULL,email TEXT NOT NULL,user_id TEXT,payload TEXT NOT NULL,expires_at INTEGER NOT NULL,epoch INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS auth_account_tokens_expiry ON auth_account_tokens(expires_at);
CREATE TABLE IF NOT EXISTS auth_recent_sessions(token_hash TEXT PRIMARY KEY,authenticated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_throttle(key TEXT PRIMARY KEY,window_start INTEGER NOT NULL,attempts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_policy_events(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,before_policy TEXT NOT NULL,after_policy TEXT NOT NULL,created_at INTEGER NOT NULL);
